from lib import *
c = []
def case(n, prefix, anns, call, exp): c.append((n, prefix + ov(*anns) + call, exp))
D = "def g() -> dict[str, type[C]]: ...\nd = g()\n"
case('posonly missing unannotated', '', ['x, /', ''], 'f()', ['RB'])
case('posonly missing unannotated2', '', ['x, /, y: type[A] = A', 'y: object = None'], 'f(y=A)', ['RB'])
case('posonly kw to kwargs', '', ['x: type[A], /, **kw: type[C]', 'x: object, /, **kw: object'], 'f(A, x=C)', ['RA'])
case('posonly kw to kwargs bad', '', ['x: type[A], /, **kw: type[A]', 'x: object, /, **kw: object'], 'f(A, x=C)', ['RB'])
case('posonly unknownkey', D, ['x: type[A] = A, /, **kw: object', 'x: object = None, /, **kw: object'], 'f(**d)', ['RA'])
case('kwonly default positional', '', ['*, x: type[A] = A', '*a: object'], 'f(A)', ['RB'])
case('kwonly after args', '', ['*a: type[C], x: type[A] = A', '*a: object'], 'f(C, C)', ['RA'])
case('kwonly after args kw', '', ['*a: type[C], x: type[A] = A', '*a: object, x: object = None'], 'f(C, x=C)', ['RB'])
case('kwonly required by kw', '', ['*, x: type[A]', 'x: object'], 'f(x=A)', ['RA'])
case('kwonly with star var', 'xs = [A] if random.random() else []\n', ['x: type[C] = C, *, y: type[A] = A', 'x: object = None, *, y: object = None'], 'f(*xs, y=A)', ['RB'])
case('kwonly star 2', 'xs = [C]\n', ['x: type[C], *, y: type[A] = A', 'x: object = None, y: object = None'], 'f(*xs)', ['RA'])
case('ukey default no kwargs', D, ['x: type[A] = A', 'x: type[C] = C'], 'f(**d)', ['RB'])
case('ukey default kwargs', D, ['x: type[A] = A, **kw: object', 'x: object = None, **kw: object'], 'f(**d)', ['RB'])
case('ukey kwonly', D, ['*, x: type[A] = A, **kw: object', '*, x: object = None, **kw: object'], 'f(**d)', ['RB'])
case('ukey filled pos', D, ['x: type[A], **kw: object', 'x: object, **kw: object'], 'f(A, **d)', ['RA'])
case('ukey filled kw', D, ['x: type[A] = A, **kw: object', 'x: object = None, **kw: object'], 'f(x=A, **d)', ['RA'])
case('ukey two dicts', "k1 = str(1)\nk2 = str(2)\n", ['x: type[A] = A, **kw: object', 'x: object = None, **kw: object'], 'f(**{k1: A}, **{k2: C})', ['RB'])
case('ukey two dicts ok', "k1 = str(1)\nk2 = str(2)\n", ['x: type[A] = A, **kw: type[A]', 'x: object = None, **kw: object'], 'f(**{k1: A}, **{k2: B})', ['RA'])
case('ukey then known', "k1 = str(1)\n", ['x: type[A] = A, y: type[A] = A, **kw: object', 'x: object = None, y: object = None, **kw: object'], 'f(**{k1: C}, y=A)', ['RB'])
case('ukey args param', D, ['*a: type[A], **kw: object', '*a: object, **kw: object'], 'f(**d)', ['RA'])
case('ukey self method', D + "class K:\n" + ov('self, x: type[A] = A, **kw: object', 'self, x: object = None, **kw: object', name='m', indent='    '), [], 'K().m(**d)', ['RB'])
case('ukey classmethod cls', D + "class K:\n" + ov('cls, **kw: object', 'cls, x: object = None, **kw: object', name='m', indent='    ', deco='@classmethod'), [], 'K.m(**d)', ['RA'])
case('walrus pos', '', ['x: type[A]', 'x: object'], 'f(y := C)', ['RB'])
case('walrus star', '', ['x: type[A]', 'x: object'], 'f(*(y := [C]))', ['RB'])
case('walrus in list', '', ['x: list[type[A]]', 'x: object'], 'f([y := C])', ['RB'])
case('walrus kw named x', '', ['x: type[C], y: type[A] = A', 'x: object, y: object = None'], 'f(y := C)', ['RA'])
case('walrus dict val', '', ['x: dict[str, type[A]]', 'x: object'], 'f({"a": (y := C)})', ['RB'])
run(c)
